    pub fn offsets_limitorder() {
        assert_eq!(
            core::mem::offset_of!(LimitOrder, lb_pair),
            0,
            "LimitOrder.lb_pair"
        );
        assert_eq!(
            core::mem::offset_of!(LimitOrder, owner),
            32,
            "LimitOrder.owner"
        );
        assert_eq!(
            core::mem::offset_of!(LimitOrder, bin_count),
            64,
            "LimitOrder.bin_count"
        );
        assert_eq!(
            core::mem::offset_of!(LimitOrder, _padding_0),
            66,
            "LimitOrder._padding_0"
        );
        assert_eq!(
            core::mem::offset_of!(LimitOrder, padding_1),
            80,
            "LimitOrder.padding_1"
        );
    }
    impl Flatten for LimitOrder {
        fn flatten(&self, path: &str, out: &mut Vec<(String, String)>) {
            let prefix = if path.is_empty() {
                String::new()
            } else {
                format!("{}.", path)
            };
            out.push((format!("{}{}", prefix, "lbPair"), bs58(&self.lb_pair)));
            out.push((format!("{}{}", prefix, "owner"), bs58(&self.owner)));
            out.push((format!("{}{}", prefix, "binCount"), {
                let v = self.bin_count;
                v.to_string()
            }));
            {
                let a0 = self._padding_0;
                for i0 in 0..14 {
                    out.push((
                        format!("{}[{}]", format!("{}{}", prefix, "padding0"), i0),
                        {
                            let v = a0[i0];
                            v.to_string()
                        },
                    ));
                }
            }
            {
                let a0 = self.padding_1;
                for i0 in 0..4 {
                    out.push((
                        format!("{}[{}]", format!("{}{}", prefix, "padding1"), i0),
                        {
                            let v = a0[i0];
                            v.to_string()
                        },
                    ));
                }
            }
        }
    }
